import { describe, expect, test } from "bun:test"
import { readFileSync } from "fs"
import { join } from "path"
import { readRoomView, readRoomRow, readRoomPerson, readParticipant, readRoomAgent, chainLine, presentLine, agentLines } from "./workspace-rooms-core"

// The room contract (#194603). These fixtures are the server's real responses, generated by
// fl-iris-api tests/Feature/Rooms/RoomsContractTest.php (see test/fixture/rooms-contract/README.md).
// The same files sit on the Desktop branch (iris/1.18.23), which reads them with its own client.
// Every field `iris workspace rooms|open|watch` and `iris agents join|role` print must come out
// right — a server rename shows up here as a wrong line, not as an empty room.

const dir = join(import.meta.dir, "..", "..", "..", "test", "fixture", "rooms-contract")
const fixture = (name: string) => JSON.parse(readFileSync(join(dir, `${name}.json`), "utf-8"))

describe("rooms contract — the CLI reads the server's real room responses (#194603)", () => {
  test("watch: the agents and the one lead, the hand-off chain, who is here", () => {
    const v = readRoomView(fixture("show"))
    expect(v.name).toBe("Launch plan")
    expect(v.project).toBe("Pricing launch")
    expect(v.agents.map((a) => [a.name, a.role, a.alwaysOn])).toEqual([
      ["Planner", "lead", false],
      ["Researcher", "participant", true],
      ["Writer", "participant", false],
    ])
    expect(v.agents.filter((a) => a.role === "lead")).toHaveLength(1)
    // The server ran with 5 turns / 2 hops; nothing here falls back to a default.
    expect(v.chain).toEqual({ depth: 2, turns: 3, maxTurns: 5, maxHops: 2 })
    expect(chainLine(v.chain)).toBe("agents are talking · 3 of 5")
    expect(presentLine(v.present)).toBe("here: Flo Rivera (typing…), Alex Mayo (away)")
    expect(agentLines(v.agents)).toEqual([
      "Planner — lead (takes your request first, hands parts to the others)",
      "Researcher — answers everything",
      "Writer — answers when @mentioned",
    ])
  })

  test("rooms: a teammate's list row — sessions, agents, unread, who is here, the latest line", () => {
    const list = fixture("list")
    expect(Array.isArray(list.data)).toBe(true)
    const r = readRoomRow(list.data[0])
    expect(r).toMatchObject({ name: "Launch plan", sessions: ["ses_alex"], messages: 1, unread: 1, working: true, last: "Alex Mayo: Plan the launch" })
    expect(r.agents.map((a) => a.role)).toEqual(["lead", "participant", "participant"])
    expect(r.present.map((p) => [p.name, p.away, p.typing])).toEqual([
      ["Flo Rivera", false, true],
      ["Alex Mayo", true, false],
    ])
  })

  test("open --agents --lead: the created room reads back with its lead", () => {
    const agents = readRoomView(fixture("store")).agents
    expect(agents.map((a) => [a.name, a.role, a.alwaysOn])).toEqual([
      ["Planner", "lead", false],
      ["Researcher", "participant", true],
    ])
  })

  test("join --role lead and role lead: the participant comes back as the lead", () => {
    for (const name of ["add-agent", "update-agent"]) {
      const p = readParticipant(fixture(name))
      expect(p?.role).toBe("lead")
      expect(p?.agentId).toMatch(/^[0-9]+$/)
      expect(typeof p?.alwaysOn).toBe("boolean")
    }
  })

  test("presence: who is here", () => {
    expect(fixture("presence").present.map(readRoomPerson)).toEqual([
      { name: "Flo Rivera", away: false, typing: true },
      { name: "Alex Mayo", away: true, typing: false },
    ])
    expect(readRoomAgent(fixture("show").thread.agents[0]).name).toBe("Planner")
  })
})
